struct net *get_net_ns_by_id(struct net *net, int id) {
    if (id < 0)
        return NULL;

    read_lock(&net_namespace_lock);
    spin_lock(&net->nsid_lock);
    struct net *target_net = find_net_ns_by_id(net, id);
    if (target_net) {
        if (!atomic_long_inc_not_zero(&target_net->count))
            target_net = NULL;
    }
    spin_unlock(&net->nsid_lock);
    read_unlock(&net_namespace_lock);

    return target_net;
}
